// Title-driven filter: only show the photo if the recipe title clearly matches
// the photo's visual category. Every ambiguous case falls back to emoji.
// 68 categories, each with a strict title regex. Order: specific → general.
function imgAllowedForRecipe(url, recipe) {
  if (!url || !recipe) return false;
  const m = url.match(/photo-(\d+)/);
  if (!m) return false;
  const prefix = m[1].split('-')[0];
  const cat = PHOTO_CATS[prefix];
  if (!cat) return false;
  const t = (recipe.title || '').toLowerCase();
  const ml = (recipe.meal  || '').toLowerCase();
  const c = (recipe.cuisine || '').toLowerCase();

  // === SPECIFIC PASTA ===
  if (cat === 'spaghetti')      return /\bspaghetti\b|aglio|cacio/.test(t);
  if (cat === 'carbonara')      return /\bcarbonara\b/.test(t);
  if (cat === 'bolognese')      return /bolognese|rag[uù]/.test(t);
  if (cat === 'penne')          return /\bpenne\b|arrabbiata/.test(t);
  if (cat === 'fettuccine')     return /fettuccine|alfredo/.test(t);
  if (cat === 'lasagna')        return /lasagn[ae]/.test(t);
  if (cat === 'gnocchi')        return /\bgnocchi\b/.test(t);
  if (cat === 'pesto_pasta')    return /\bpesto\b/.test(t);
  if (cat === 'mushroom_pasta') return /mushroom.*pasta|creamy.*pasta/.test(t);
  if (cat === 'pasta_generic')  return /pasta|linguine|rigatoni|fusilli|macaroni|mac |orzo|tortellini|ravioli|ziti|farfalle|primavera|caponata|amatriciana/.test(t);

  // === NOODLES / ASIAN ===
  if (cat === 'ramen')     return /\bramen\b/.test(t);
  if (cat === 'pad_thai')  return /pad\s*thai/.test(t);
  if (cat === 'pho')       return /\bpho\b/.test(t);
  if (cat === 'soba')      return /\bsoba\b/.test(t);
  if (cat === 'lo_mein')   return /lo\s*mein/.test(t);
  if (cat === 'noodles')   return /noodle|udon|char kway|mee goreng|laksa/.test(t);

  // === RICE ===
  if (cat === 'fried_rice') return /fried rice|nasi goreng|pilaf|plov|rice|makloubeh|maqluba/.test(t);
  if (cat === 'biryani')    return /\bbiryani\b/.test(t);
  if (cat === 'paella')     return /\bpaella\b/.test(t);
  if (cat === 'risotto')    return /\brisotto\b/.test(t);
  if (cat === 'bibimbap')   return /bibimbap|bibim guksu/.test(t);

  // === CURRY ===
  if (cat === 'curry')      return /curry|masala|tikka|korma|vindaloo|saag|palak|\bdal[^a-z]|daal|dhal|rajma|chole|dhansak|keema|fesenjan|ghormeh/.test(t);
  if (cat === 'thai_curry') return /thai.*curry|green.*curry|red.*curry|massaman|panang/.test(t);

  // === SOUPS ===
  if (cat === 'soup')        return /soup|chowder|bisque|stew|chili|goulash|gazpacho|harira|borscht|caldo|avgolemono|ribollita|scotch broth|shorba|gumbo|jambalaya|feijoada|tagine|lentil/.test(t);
  if (cat === 'lentil_soup') return /lentil.*soup|lentil/.test(t);
  if (cat === 'minestrone')  return /\bminestrone\b/.test(t);
  if (cat === 'tom_yum')    return /tom\s*yum|tom\s*kha/.test(t);
  if (cat === 'french_stew') return /bourguignon|cassoulet|pot au feu|bouillabaisse|coq au vin/.test(t);

  // === SALADS ===
  if (cat === 'salad') return /salad|slaw|tabbouleh|fattoush/.test(t);

  // === PROTEINS ===
  if (cat === 'chicken')         return /chicken|pollo|peking duck/.test(t);
  if (cat === 'grilled_chicken') return /chicken.*(grilled|roast|baked)|grilled.*chicken/.test(t);
  if (cat === 'salmon')          return /\bsalmon\b/.test(t);
  if (cat === 'fish')            return /fish|cod |tilapia|mahi|halibut|trout|sea bass|snapper|sole|branzino/.test(t);
  if (cat === 'shrimp')          return /shrimp|prawn|calamari|crab|lobster|scallop/.test(t);
  if (cat === 'tuna')            return /\btuna\b/.test(t);
  if (cat === 'steak')           return /steak|beef|lamb|gosht|pork|pulled|pigs in|bistecca|tonkatsu|schnitzel/.test(t);
  if (cat === 'seafood')         return /seafood|ceviche|pescado|camarones/.test(t);
  if (cat === 'tofu')            return /tofu|tempeh/.test(t);

  // === VEGETABLE DISHES ===
  if (cat === 'ratatouille') return /ratatouille|stuffed|rollatini|parmigiana|grilled|roasted|roast|baked|braised|sauteed|saut[eé]ed|vegetable/.test(t) || (ml === 'dinner' && !(/chicken|beef|pork|lamb|fish|shrimp|salmon/).test(t));

  // === SANDWICHES / TOAST / WRAPS ===
  if (cat === 'sandwich')    return /sandwich|panini|club|blt|grilled cheese|melt|bagel|focaccia|croque|b[aá]nh m[iì]|pita|croissant|sub /.test(t);
  if (cat === 'toast')       return /toast|bruschetta|crostini|pan con|scone|muffin|biscuit|bread/.test(t);
  if (cat === 'wrap')        return /\bwrap\b|burrito(?!.*bowl)/.test(t);
  if (cat === 'avocado_toast') return /avocado.*toast|avo.*toast/.test(t);
  if (cat === 'french_toast')  return /french toast|pain perdu/.test(t);

  // === BREAKFAST ===
  if (cat === 'pancakes')        return /pancake|hotcake|pannkakor/.test(t);
  if (cat === 'waffles')         return /\bwaffle/.test(t);
  if (cat === 'crepe')           return /cr[eê]pe/.test(t);
  if (cat === 'oatmeal')         return /oatmeal|porridge|muesli|overnight oats|granola/.test(t);
  if (cat === 'eggs')            return /egg|scramble|benedict|quiche|huevos|migas|chilaquiles|gyeran|tortilla/.test(t);
  if (cat === 'shakshuka')       return /shakshuka|menemen/.test(t);
  if (cat === 'frittata')        return /\bfrittata\b/.test(t);
  if (cat === 'omelette')        return /omelette?|omelet/.test(t);
  if (cat === 'yogurt')          return /yogurt|parfait|cottage cheese/.test(t);
  if (cat === 'smoothie_bowl')   return /smoothie.*bowl|bowl/.test(t) && ml === 'breakfast';
  if (cat === 'smoothie')        return /smoothie|shake/.test(t);
  if (cat === 'chia_pudding')    return /\bchia\b/.test(t);
  if (cat === 'breakfast_plate') return ml === 'breakfast';

  // === MEXICAN ===
  if (cat === 'tacos')             return /taco|fajita|tostada/.test(t);
  if (cat === 'burrito_bowl')      return /burrito.*bowl/.test(t);
  if (cat === 'quesadilla')        return /quesadilla/.test(t);
  if (cat === 'enchilada')         return /enchilada/.test(t);
  if (cat === 'breakfast_burrito') return /breakfast.*burrito/.test(t);
  if (cat === 'mexican_dish')      return /tamale|carnita|cochinita|tinga|mole|chiles|rajas|sopa azteca|pozole|sopa de lima|torta/.test(t) || c === 'mexican';

  // === MIDDLE EASTERN ===
  if (cat === 'shawarma') return /\bshawarma\b/.test(t);
  if (cat === 'falafel')  return /\bfalafel\b/.test(t);
  if (cat === 'hummus')   return /hummus|labneh|baba|muhammara|moutabel|tzatziki|ajvar|tapenade|skordalia|dukkah|raita|ranch|guacamole|peanut sauce|dip|spread|fondue/.test(t);
  if (cat === 'kebab')    return /kebab|skewer|satay|kofta|kofte|seekh/.test(t);

  // === PIZZA / BURGER ===
  if (cat === 'pizza')  return /pizza|flatbread/.test(t);
  if (cat === 'burger') return /burger|slider/.test(t);

  // === DUMPLINGS / ASIAN SMALL ===
  if (cat === 'dumplings')    return /dumpling|gyoza|wonton|potsticker|pot sticker|dim sum|pierogi|samosa|pakora|bhaji|arancini|croqueta|fritter|poppers|fries|rings|crisps|sticks|tempura|buffalo|battered|halloumi|edamame|kibbeh|b[oö]rek|g[oö]z/.test(t);
  if (cat === 'spring_rolls') return /spring roll|egg roll|summer roll/.test(t);
  if (cat === 'sushi')        return /sushi|maki/.test(t);

  // === STIR FRY ===
  if (cat === 'stir_fry') return /stir.?fry|phad see|pad see|pad prik|pad woon|larb|adobo|lomo saltado/.test(t) || (c === 'japanese' || c === 'chinese');

  // === DESSERT ===
  if (cat === 'dessert') return /cake|brownie|cookie|tart|cheesecake|crumble|galette|pudding/.test(t);

  // === BOWLS ===
  if (cat === 'grain_bowl') return /bowl|grain|buddha|quinoa|chickpea|nourish|harvest|kushari|koshari|mjaddara|mujaddara|couscous/.test(t);

  // === CUISINE-SPECIFIC BROADER CATEGORIES ===
  if (cat === 'korean_dish')     return c === 'korean' || /bibimbap|bulgogi|sundubu|jjigae|doenjang|oyakodon|nikujaga|banchan|tteok/.test(t);
  if (cat === 'french_dish')     return c === 'french' || /bourguignon|daurade|souffl[eé]|camembert|fromage|remoulade/.test(t);
  if (cat === 'italian_dish')    return c === 'italian' || /osso buco|porchetta|saltimbocca|caprese|antipasto|prosciutto|fagioli|tiella|caponata/.test(t);
  if (cat === 'greek_dish')      return c === 'greek' || c === 'cypriot' || /moussaka|musakka|dolmades|gigantes/.test(t);
  if (cat === 'turkish_dish')    return c === 'turkish' || /g[oö]zleme|b[oö]rek|imam|simit/.test(t);
  if (cat === 'ethiopian_dish')  return c === 'ethiopian' || /injera|fit-fit|beyaynetu|misir|wot/.test(t);
  if (cat === 'british_dish')    return /wellington|shepherd.*pie|british|scottish/.test(t) || ['british','scottish','irish','austrian','polish','swiss'].includes(c);
  if (cat === 'indian_dish')     return c === 'indian' || c === 'pakistani' || c === 'bangladeshi' || /aloo|baingan|bharta|paratha|ful medames/.test(t);
  if (cat === 'southeast_asian') return /laksa|soto|gado gado|nasi lemak/.test(t) || ['thai','malaysian','indonesian','filipino','vietnamese','penang'].includes(c);
  if (cat === 'middle_eastern')  return ['middle eastern','lebanese','israeli','syrian','palestinian','jordanian','egyptian','north african','moroccan','persian'].includes(c);
  if (cat === 'latin_american')  return ['mexican','peruvian','brazilian'].includes(c);

  // === SNACK FALLBACKS ===
  if (cat === 'snack_plate') return ml === 'snack';
  if (cat === 'appetizer')   return ml === 'snack';

  return false;
}

// ── PlannerThumb ──────────────────────────────────────────────────────────────
// Full-width image filling the meal slot, with the meal name as a bottom
// gradient overlay. Falls back to emoji+name if image is absent or fails.
function PlannerThumb({ recipe, mealName, emoji, showShopping }) {
  const [failed, setFailed] = React.useState(false);
  const imgSrc = recipe?.image;
  const show = imgSrc && !failed && imgAllowedForRecipe(imgSrc, recipe);
  if (show) {
    return (
      <div style={{width:'100%',position:'relative',borderRadius:6,overflow:'hidden',height:72,flexShrink:0}}>
        <img
          src={imgSrc}
          alt={mealName}
          style={{position:'absolute',inset:0,width:'100%',height:'100%',objectFit:'cover',display:'block'}}
          onError={()=>setFailed(true)}
        />
        <div style={{position:'absolute',inset:0,background:'linear-gradient(transparent 30%,rgba(0,0,0,0.72) 100%)',pointerEvents:'none'}} />
        <div style={{position:'absolute',bottom:0,left:0,right:0,padding:'0 5px 5px',textAlign:'center'}}>
          <div style={{fontSize:11,fontWeight:700,color:'#fff',lineHeight:1.25,textShadow:'0 1px 4px rgba(0,0,0,0.95)',overflow:'hidden',display:'-webkit-box',WebkitLineClamp:2,WebkitBoxOrient:'vertical'}}>{mealName}</div>
          {showShopping && <div style={{fontSize:9,color:'#FFD86B',fontWeight:700,marginTop:1,textShadow:'0 1px 3px rgba(0,0,0,0.9)'}}>🛒</div>}
        </div>
      </div>
    );
  }
  return (
    <>
      <div className="msem">{emoji || recipe?.emoji || '🍽️'}</div>
      <div className="msn">{mealName}</div>
      {showShopping && <div style={{fontSize:10,color:'var(--gold)',fontWeight:600,marginTop:2}}>🛒 Needs shopping</div>}
    </>
  );
}

// ── PlanMosaicPreview ─────────────────────────────────────────────────────────
// 2×2 image grid for plan cards. Tracks per-tile load errors via React state;
// shows emoji fallback when fewer than 2 tiles load successfully.
function PlanMosaicPreview({ images, fallbackEmoji }) {
  const [errors, setErrors] = React.useState({});
  const markError = React.useCallback(i => setErrors(v => ({...v,[i]:true})), []);
  const goodCount = images.filter((_,i) => !errors[i]).length;
  if (goodCount < 2) {
    return <div className="plan-card-emoji">{fallbackEmoji || '\ud83d\udccb'}</div>;
  }
  return (
    <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:2,width:52,height:52,borderRadius:8,overflow:'hidden',marginBottom:8}}>
      {images.slice(0,4).map((img,i) => errors[i] ? null : (
        <img key={i} src={img} alt=""
          style={{width:'100%',height:'100%',objectFit:'cover',display:'block'}}
          onError={()=>markError(i)}
        />
      ))}
    </div>
  );
}

// ── RecipeImg ─────────────────────────────────────────────────────────────────
// Used by RecipeCard (.rimg container) and RecipeDetail hero.
// React state tracks load failure so emoji renders correctly — no empty boxes.
function RecipeImg({ recipe, style, emojiSize }) {
  const [failed, setFailed] = React.useState(false);
  const img = recipe?.image;
  if (img && !failed && imgAllowedForRecipe(img, recipe)) {
    return (
      <img
        src={img}
        alt={recipe?.title || ''}
        style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block', ...style }}
        onError={() => setFailed(true)}
      />
    );
  }
  // Emoji placeholder — renders when no image, when quality filter rejects it,
  // or when the image fails to load from the CDN.
  return (
    <span style={{ fontSize: emojiSize || 72, lineHeight: 1 }}>
      {recipe?.emoji || '\ud83c\udf7d\ufe0f'}
    </span>
  );
}

function RecipeCard({ r, saved, onSave, onView, addToList, inFav, pantry, onAddToWeek }) {
  // STEP 4 STABILIZATION: Compute missing ingredients dynamically from pantry.
  // Do NOT use the static r.missing field for display — it is hardcoded and not pantry-aware.
  const dynamicMissing = React.useMemo(() => {
    if (r.isUserCreated || !r.ingredients?.length) return [];
    const ps = buildPantrySet(pantry || []);
    return r.ingredients
      .filter(i => !ingInPantry(i.n, ps))
      .map(i => i.n);
  }, [r.id, r.ingredients, pantry]);

  // Pantry match % (dynamic, replaces static r.pp)
  const dynamicPP = r.ingredients?.length
    ? Math.round(((r.ingredients.length - dynamicMissing.length) / r.ingredients.length) * 100)
    : (r.pp || 0);

  const handleAddMissing = () => addToList(dynamicMissing);

  // 3-dot popover state
  const [popOpen, setPopOpen] = useState(false);
  const popRef = useRef(null);
  useEffect(() => {
    if (!popOpen) return;
    const handler = (e) => {
      if (popRef.current && !popRef.current.contains(e.target)) setPopOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [popOpen]);

  return (
    <div className="card">
      <div className="rimg" onClick={onView}>
        <RecipeImg recipe={r}/>
        <div className="rtag">{r.cuisine}</div>
        {r.worth && <div className="rbadge">⭐ Worth buying</div>}
        {r.isUserCreated && <div className="rbadge" style={{background:"var(--sage)"}}>My Recipe</div>}
        {/* ── 3-dot menu ── */}
        <button
          className="card-dot-btn"
          onClick={e=>{e.stopPropagation();setPopOpen(v=>!v);}}
          aria-label="Recipe options"
        >⋯</button>
        {popOpen && (
          <div className="card-popover" ref={popRef} onClick={e=>e.stopPropagation()}>
            <button className="card-pop-item" onClick={()=>{setPopOpen(false);onView();}}>
              <Ic n="list" s={14}/>View recipe
            </button>
            {onAddToWeek && (
              <button className="card-pop-item" onClick={()=>{setPopOpen(false);onAddToWeek(r);}}>
                <Ic n="cal" s={14}/>Add to week
              </button>
            )}
            <div className="card-pop-divider"/>
            <button className="card-pop-item" onClick={e=>{e.stopPropagation();setPopOpen(false);onSave(r);}}>
              <Ic n={saved?"bookmarkOn":"bookmark"} s={14}/>{saved?"Saved ✓":"Save recipe"}
            </button>
            {dynamicMissing.length > 0 && (
              <>
                <div className="card-pop-divider"/>
                <button className="card-pop-item" onClick={()=>{setPopOpen(false);handleAddMissing();}}>
                  <Ic n="cart" s={14}/>Add missing to list
                </button>
              </>
            )}
          </div>
        )}
      </div>
      <div className="rbody">
        <div className="rtitle" onClick={onView}>{r.title}</div>
        <div className="rmeta"><span className="rmeta-i">⏱ {r.time} min</span><span className="rmeta-i">📊 {r.diff}</span></div>
        <div className="rtags">{r.dietary.map(d=><span key={d} className="tag td">{d}</span>)}</div>
        {!r.isUserCreated && (
          <div className="pbar">
            <div className="pbar-r">
              <span>Pantry match</span>
              <span style={{color:"var(--sage)",fontWeight:600}}>{dynamicPP}%</span>
            </div>
            <div className="pbar-t"><div className="pbar-f" style={{width:`${dynamicPP}%`}}/></div>
          </div>
        )}
        {dynamicMissing.length > 0 && (
          <div style={{fontSize:12,color:"var(--mu)",marginBottom:8}}>
            Missing: {dynamicMissing.slice(0,3).join(", ")}{dynamicMissing.length > 3 ? ` +${dynamicMissing.length - 3} more` : ""}
          </div>
        )}
        <div className="ractions">
          <button className="btn btn-sm btn-cs" onClick={onView}>View</button>
          {onAddToWeek && (
            <button className="btn btn-sm btn-s" onClick={()=>onAddToWeek(r)} title="Add to week">
              <Ic n="cal" s={13}/>
            </button>
          )}
          <button
            className={`bm-btn ${saved?"on":""}`}
            onClick={e=>{e.stopPropagation();onSave(r);}}
            title={inFav?"Remove from favorites":"Save to favorites"}
          >
            <Ic n={saved?"bookmarkOn":"bookmark"} s={15}/>
          </button>
        </div>
      </div>
    </div>
  );
}

/* ── RANDOM MODAL ── */
function RandomModal({ onClose, onView, addToList }) {
  const [step,setStep]=useState("filters");
  const [result,setResult]=useState(null);
  const [f,setF]=useState({cuisine:"Any",style:"Any",maxTime:60});
  const STYLES=["Any","Quick","Romantic","Comfort","Healthy","High protein","Vegetarian","Vegan"];
  const CUIS=["Any","Italian","Japanese","Mediterranean","Mexican","Indian","French","Middle Eastern"];
  const generate=()=>{const pool=RECIPES.filter(r=>{if(f.cuisine!=="Any"&&r.cuisine!==f.cuisine)return false;if(r.time>f.maxTime)return false;if(f.style==="Vegetarian"&&!r.dietary.includes("Vegetarian"))return false;if(f.style==="Vegan"&&!r.dietary.includes("Vegan"))return false;return true;});setResult(pool.length>0?pool[Math.floor(Math.random()*pool.length)]:RECIPES[Math.floor(Math.random()*RECIPES.length)]);setStep("result");};
  return (
    <div className="mov" onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div className="modal">
        <div className="mhd"><div className="mtitle">{step==="filters"?"🎲 Random Plate":"Here's your plate!"}</div><button className="mclose" onClick={onClose}><Ic n="x" s={16}/></button></div>
        {step==="filters"&&<div className="mbody" style={{display:"flex",flexDirection:"column",gap:16}}>
          <div><label className="fl">Cuisine</label><select className="sel" value={f.cuisine} onChange={e=>setF(p=>({...p,cuisine:e.target.value}))}>{CUIS.map(c=><option key={c}>{c}</option>)}</select></div>
          <div><label className="fl">Style</label><div className="mopts">{STYLES.map(s=><button key={s} className={`mopt ${f.style===s?"sel":""}`} onClick={()=>setF(p=>({...p,style:s}))}>{s}</button>)}</div></div>
          <div><label className="fl">Max cook time: {f.maxTime} min</label><input type="range" min={10} max={120} step={5} value={f.maxTime} onChange={e=>setF(p=>({...p,maxTime:+e.target.value}))} style={{width:"100%",accentColor:"var(--clay)"}}/></div>
          <button className="btn btn-p btn-full btn-lg" onClick={generate}><Ic n="shuffle" s={18}/>Surprise me!</button>
        </div>}
        {step==="result"&&result&&<div>
          <div style={{textAlign:"center",padding:"28px 20px"}}>
            <div style={{fontSize:72,marginBottom:8}}>{result.emoji}</div>
            <div style={{fontFamily:"var(--fd)",fontSize:26,marginBottom:6}}>{result.title}</div>
            <div style={{color:"var(--mu)",fontSize:14,marginBottom:16}}>{result.cuisine} · {result.time} min · {result.diff}</div>
            <div style={{display:"flex",flexWrap:"wrap",gap:6,justifyContent:"center",marginBottom:16}}>{result.dietary.map(d=><span key={d} className="tag td">{d}</span>)}</div>
            <div className="pbar" style={{textAlign:"left"}}><div className="pbar-r"><span>Pantry match</span><span style={{color:"var(--sage)",fontWeight:600}}>{result.pp}%</span></div><div className="pbar-t"><div className="pbar-f" style={{width:`${result.pp}%`}}/></div></div>
          </div>
          <div style={{padding:"0 24px 24px",display:"flex",flexDirection:"column",gap:10}}>
            <button className="btn btn-p btn-full" onClick={()=>onView(result)}>View full recipe →</button>
            <button className="btn btn-s btn-full" onClick={generate}><Ic n="shuffle" s={16}/>Generate another</button>
            {/* Missing ingredients for random recipes computed dynamically in RecipeDetail when opened */}
          </div>
        </div>}
      </div>
    </div>
  );
}


